-- PCSX-Redux boot tracer for the Chrono Cross decomp.
--
-- Logs the first time each main-EXE function runs (with the frame number),
-- saves a raw screenshot every SHOT_EVERY frames, optionally taps START,
-- then writes results and quits.
--
-- Run:  pcsx-redux.exe -iso <disc.cue> -dofile tools/trace_boot.lua
-- Expects <OUT>/funcs.lua (generated by tools/trace_funcs.py).

local OUT = TRACE_OUT or 'C:/Users/delan/Documents/ChronoCross/build/trace'
local MAX_FRAMES = TRACE_MAX_FRAMES or 60 * 90   -- 90 s of game time
local SHOT_EVERY = TRACE_SHOT_EVERY or 60 * 5    -- every 5 s
local START_TAPS = TRACE_START_TAPS or {}        -- frames at which to tap START

-- LuaJIT has about 1000 FFI callback slots and each breakpoint takes one,
-- so trace one category per run: 'g' = game code, 'l' = PsyQ libraries.
local SET = TRACE_SET or 'g'
local funcs = dofile(OUT .. '/funcs.lua')

-- Breakpoints need the debugger; the interpreter keeps timing exact.
-- These only take effect at the next emulator start (they are saved to
-- pcsx.json), so the very first run after changing them traces nothing.
if not (PCSX.settings.emulator.Debug.Debug and not PCSX.settings.emulator.Dynarec) then
    PCSX.settings.emulator.Debug.Debug = true
    PCSX.settings.emulator.Dynarec = false
    print('trace: enabled debugger + interpreter; restart PCSX-Redux and run again')
end

local frame = 0
local order = 0
local hits = {}
BPS = {}  -- global so the breakpoints are not garbage-collected

local notes = {}
local function note(s) notes[#notes + 1] = s; print('trace: ' .. s) end

-- The BIOS boot animation runs from the same RAM the game later uses, so only
-- arm the per-function breakpoints once the game's EXE entry point runs.
local ENTRY = 0x80010008
local function armAll()
    for _, f in ipairs(funcs) do
        local addr, name, cat = f[1], f[2], f[3]
        if cat == SET and addr ~= ENTRY then
            BPS[#BPS + 1] = PCSX.addBreakpoint(addr, 'Exec', 4, 'trace', function()
                order = order + 1
                hits[#hits + 1] = string.format('%d,%d,%08X,%s', order, frame, addr, name)
                return false -- remove after the first hit
            end, name)
        end
    end
    note(string.format('EXE entry at frame %d; %d breakpoints armed', frame, #BPS))
end
ENTRY_BP = PCSX.addBreakpoint(ENTRY, 'Exec', 4, 'entry', function()
    order = order + 1
    hits[#hits + 1] = string.format('%d,%d,%08X,%s', order, frame, ENTRY, 'start')
    armAll()
    return false
end, 'entry')

local function writeText(path, text)
    local f = Support.File.open(path, 'TRUNCATE')
    f:write(text)
    f:close()
end

local function screenshot(tag)
    local ok, err = pcall(function()
        local ss = PCSX.GPU.takeScreenShot()
        local bpp = (tostring(ss.bpp) == 'BPP_24' or ss.bpp == 1) and 24 or 16
        local f = Support.File.open(string.format('%s/shot_%s.raw', OUT, tag), 'TRUNCATE')
        f:writeMoveSlice(ss.data)
        f:close()
        writeText(string.format('%s/shot_%s.txt', OUT, tag), string.format('%d %d %d\n', ss.width, ss.height, bpp))
    end)
    if not ok then print('trace: screenshot failed: ' .. tostring(err)) end
end

local function pad(button, down)
    pcall(function()
        local p = PCSX.SIO0.slots[1].pads[1]
        if down then p.setOverride(button) else p.clearOverride(button) end
    end)
end

local tapAt = {}
for _, t in ipairs(START_TAPS) do tapAt[t] = true end
local releaseAt = {}

local function finish()
    writeText(OUT .. '/hits_' .. SET .. '.csv','order,frame,addr,name\n' .. table.concat(hits, '\n') .. '\n')
    writeText(OUT .. '/done.txt', string.format('frames=%d hits=%d\n', frame, #hits) .. table.concat(notes, '\n') .. '\n')
    print(string.format('trace: done at frame %d, %d functions hit', frame, #hits))
    PCSX.quit(0)
end

TRACE_LISTENER = PCSX.Events.createEventListener('GPU::Vsync', function()
    frame = frame + 1
    if tapAt[frame] then
        local ok, err = pcall(function()
            local p = PCSX.SIO0.slots[1].pads[1]
            p.setOverride(PCSX.CONSTS.PAD.BUTTON.START)
        end)
        releaseAt[frame + 6] = true
        note('START down at frame ' .. frame .. (ok and '' or (' FAILED: ' .. tostring(err))))
    end
    if releaseAt[frame] then pcall(function() pad(PCSX.CONSTS.PAD.BUTTON.START, false) end) end
    if frame % SHOT_EVERY == 0 then
        screenshot(string.format('%05d', frame))
        -- save progress so a hang still leaves a usable log
        writeText(OUT .. '/hits_' .. SET .. '.csv', 'order,frame,addr,name\n' .. table.concat(hits, '\n') .. '\n')
    end
    if frame >= MAX_FRAMES then finish() end
end)

PCSX.resumeEmulator()
